trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct Rtri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}
impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}
impl Shape for Rtri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}
impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn num(s: string) -> int {
    s.parse::<int>() ?? 0
}

fn main() {
    let text = std::fs::read_to_string("/dev/stdin") ?? ""
    let mut total = 0
    let mut best = -1
    let mut best_name = ""
    let mut count = 0
    for line in text.lines() {
        let p = std::strings::split_whitespace(line)
        if p.len() == 0 {
            continue
        }
        let kind = p[0]
        let shape: Box<dyn Shape> = if kind == "square" {
            Box::new(Square { s: num(p[1]) })
        } else if kind == "rect" {
            Box::new(Rect { w: num(p[1]), h: num(p[2]) })
        } else if kind == "rtri" {
            Box::new(Rtri { a: num(p[1]), b: num(p[2]) })
        } else {
            Box::new(Trap { a: num(p[1]), b: num(p[2]), h: num(p[3]) })
        }
        let d = shape.double_area()
        println("${shape.name()} corners=${shape.corners()} area2=${d}")
        total = total + d
        if d > best {
            best = d
            best_name = shape.name()
        }
        count = count + 1
    }
    println("total area2=${total}")
    if count == 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

